func validateDataColumnsByRootRequest(colIdents types.DataColumnsByRootIdentifiers) error {
  total := uint64(0)
  for _, id := range colIdents { total += uint64(len(id.Columns)) }
  if total > params.BeaconConfig().MaxRequestDataColumnSidecars { return types.ErrMaxDataColumnReqExceeded }
  return nil
}

